<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{Boxes,Clock3,History,Network,Play,Radio,RefreshCw,Search,Server,Terminal}from'lucide-vue-next';import{useAuthStore}from'@/stores/useAuthStore';import{categoryLabel,resultTone}from'@/features/toolbox/toolboxModel';type Tool={id:string;name:string;category:string;description:string;icon:string;placeholder:string;risk:string};type Line={time:string;level:string;text:string};type Result={id:string;toolId:string;toolName:string;target:string;status:string;operator:string;startedAt:string;duration:string;summary:string;output:Line[]};type Summary={tools:number;executionsToday:number;successRate:number;avgDuration:string};const auth=useAuthStore(),tools=ref<Tool[]>([]),history=ref<Result[]>([]),summary=ref<Summary>(),selectedTool=ref<Tool>(),selectedResult=ref<Result>(),target=ref('10.20.1.11'),query=ref(''),running=ref(false);const headers=computed(()=>({Authorization:`Bearer ${auth.token}`,'Content-Type':'application/json'}));const iconMap={Radio,Network,Server,Boxes,Search};async function load(){[summary.value,tools.value,history.value]=await Promise.all(['summary','tools','history'].map(x=>fetch('/api/v1/toolbox/'+x,{headers:headers.value}).then(r=>r.json())));selectedTool.value ||= tools.value[0]}async function run(){if(!selectedTool.value)return;running.value=true;const r=await fetch('/api/v1/toolbox/executions',{method:'POST',headers:headers.value,body:JSON.stringify({toolId:selectedTool.value.id,target:target.value,query:query.value})});selectedResult.value=await r.json();running.value=false;await load()}onMounted(load)</script>
<template><section class="toolbox-page"><header class="toolbox-heading"><div><span>SAFE DIAGNOSTIC WORKBENCH</span><h1>运维排查工具箱</h1><p>标准化诊断、安全执行与结果归档</p></div><button @click="load"><RefreshCw/>刷新记录</button></header><div class="toolbox-summary"><article><Terminal/><span>可用工具<strong>{{summary?.tools}}</strong></span></article><article><Play/><span>今日执行<strong>{{summary?.executionsToday}}</strong></span></article><article><Radio/><span>成功率<strong>{{summary?.successRate}}%</strong></span></article><article><Clock3/><span>平均耗时<strong>{{summary?.avgDuration}}</strong></span></article></div><div class="toolbox-workspace"><aside class="tool-menu"><h3>诊断工具</h3><button v-for="t in tools" :key="t.id" :class="{active:selectedTool?.id===t.id}" @click="selectedTool=t;selectedResult=undefined"><component :is="iconMap[t.icon as keyof typeof iconMap]"/><div><strong>{{t.name}}</strong><span>{{categoryLabel(t.category)}}</span></div></button></aside><main class="diagnostic-console"><header><div><span>ACTIVE TOOL</span><h2>{{selectedTool?.name}}</h2><p>{{selectedTool?.description}}</p></div><b :data-risk="selectedTool?.risk">{{selectedTool?.risk}} risk</b></header><form @submit.prevent="run"><label>诊断目标<input v-model="target" :placeholder="selectedTool?.placeholder"></label><label v-if="selectedTool?.category==='logs'">检索关键字<input v-model="query" placeholder="error OR timeout"></label><button class="primary" :disabled="running"><Play/>{{running?'正在执行':'开始诊断'}}</button></form><div class="terminal-output"><header><Terminal/>诊断输出 <span>{{selectedResult?.id}}</span></header><template v-if="selectedResult"><p v-for="line in selectedResult.output" :key="line.time+line.text" :data-level="line.level"><time>{{line.time}}</time><b>[{{line.level}}]</b>{{line.text}}</p><footer :data-tone="resultTone(selectedResult.status)">{{selectedResult.summary}} · 耗时 {{selectedResult.duration}}</footer></template><div v-else class="terminal-empty">等待执行诊断任务...</div></div></main><aside class="diagnostic-history"><header><History/><h3>执行记录</h3></header><button v-for="r in history" :key="r.id" :class="{active:selectedResult?.id===r.id}" @click="selectedResult=r"><i :data-tone="resultTone(r.status)"></i><div><strong>{{r.toolName}}</strong><span>{{r.target}}</span><small>{{r.operator}} · {{r.startedAt}} · {{r.duration}}</small></div></button></aside></div></section></template>
